import sys

def permute_brute(nums):
    nums = sorted(nums)
    res = []
    used = [False] * len(nums)
    def dfs(path):
        if len(path) == len(nums):
            res.append(path[:])
            return
        for j in range(len(nums)):
            if used[j]:
                continue
            if j > 0 and nums[j] == nums[j - 1] and not used[j - 1]:
                continue
            used[j] = True
            path.append(nums[j])
            dfs(path)
            path.pop()
            used[j] = False
    dfs([])
    return res

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    res = permute_brute(nums)
    for p in res:
        print(' '.join(map(str, p)))

import sys
from collections import Counter

def permute_opt(nums):
    counter = Counter(nums)
    res = []
    def dfs(path):
        if len(path) == len(nums):
            res.append(path[:])
            return
        for x in list(counter):
            if counter[x] == 0:
                continue
            path.append(x)
            counter[x] -= 1
            dfs(path)
            path.pop()
            counter[x] += 1
    dfs([])
    return sorted(res)

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    res = permute_opt(nums)
    for p in res:
        print(' '.join(map(str, p)))

